const DOMESTIC_APP_IDS = new Set<string>([
  "kuaishou",
  "douyin",
  "wechat",
  "qq",
  "bilibili",
  "weibo",
  "alipay",
  "xiaohongshu",
  "taobao",
  "meituan",
  "zhihu",
  "douban",
  "baidu",
  "neteasecloudmusic",
  "dingtalk",
  "aliwangwang",
  "sogou",
  "alibaba",
  ...POPULAR_CN_APP_ICONS.map((app) => app.id),
  ...ADDITIONAL_APP_ICONS.map((app) => app.id),
]);
export type AppIconRegion = "domestic" | "international";
export type AppIconFilter = "all" | AppIconRegion | "custom";
export const APP_ICONS = BASE_APP_ICONS.map((app) => ({
  ...app,
  region: (DOMESTIC_APP_IDS.has(app.id)
    ? "domestic"
    : "international") as AppIconRegion,
}));
const APP_ICON_REGIONS: ReadonlyMap<string, AppIconRegion> = new Map(
  APP_ICONS.map((app) => [app.id, app.region]),
);
export function matchesAppIconRegion(
  filter: AppIconFilter,
  builtinId?: string,
) {
  return (
    filter === "all" ||
    (filter === "custom"
      ? !builtinId
      : !!builtinId && APP_ICON_REGIONS.get(builtinId) === filter)
  );
}
export type BuiltinAppIconId = (typeof APP_ICONS)[number]["id"];
export const APP_ICON_IDS = APP_ICONS.map((icon) => icon.id);
export const MAX_APP_ICONS = 8;
/** Self-contained brand-colour SVG shared by the picker, canvas and exports. */
export function builtinAppIconSource(
  id: BuiltinAppIconId,
  normalize = false,
): {
  kind: "url";
  url: string;
} {
  const icon = APP_ICONS.find((icon) => icon.id === id)!;
  const paths = (fill: string, transform = "") =>
    icon.paths
      .map(
        (path) =>
          '<path fill="' +
          fill +
          '"' +
          (transform ? ' transform="' + transform + '"' : "") +
          ' d="' +
          path +
          '"/>',
      )
      .join("");
  let content =
    "imageData" in icon
      ? `<image width="100" height="100" href="${icon.imageData}"/>`
      : "svgBody" in icon
        ? icon.svgBody
        : paths(icon.color);
  if (id === "douyin") {
    content =
      '<rect width="24" height="24" rx="5" fill="#161823"/>' +
      paths("#25F4EE", "translate(-.65 .55) translate(2 2) scale(.82)") +
      paths("#FE2C55", "translate(.65 -.55) translate(2 2) scale(.82)") +
      paths("#FFFFFF", "translate(2 2) scale(.82)");
  } else if (id === "qq") {
    content =
      paths("#161823") +
      '<ellipse cx="224" cy="297" rx="111" ry="150" fill="#FFFFFF"/>' +
      '<ellipse cx="185" cy="145" rx="28" ry="44" fill="#FFFFFF"/><ellipse cx="263" cy="145" rx="28" ry="44" fill="#FFFFFF"/>' +
      '<ellipse cx="194" cy="150" rx="10" ry="19" fill="#161823"/><ellipse cx="254" cy="150" rx="10" ry="19" fill="#161823"/>' +
      '<ellipse cx="224" cy="203" rx="56" ry="18" fill="#FFB52E"/>' +
      '<path d="M78 230Q224 284 370 230L375 270Q224 325 73 270Z" fill="#EB1923"/>' +
      '<ellipse cx="141" cy="479" rx="67" ry="24" fill="#FFB52E"/><ellipse cx="307" cy="479" rx="67" ry="24" fill="#FFB52E"/>';
  } else if (id === "instagram" || id === "messenger" || id === "firefox") {
    content =
      '<defs><linearGradient id="brand" x1="0" y1="1" x2="1" y2="0">' +
      (id === "instagram"
        ? '<stop stop-color="#FEDA75"/><stop offset=".4" stop-color="#FA7E1E"/><stop offset=".65" stop-color="#D62976"/><stop offset="1" stop-color="#4F5BD5"/>'
        : id === "messenger"
          ? '<stop stop-color="#00B2FF"/><stop offset=".55" stop-color="#A033FF"/><stop offset="1" stop-color="#FF6968"/>'
          : '<stop stop-color="#FFBD4F"/><stop offset=".5" stop-color="#FF7139"/><stop offset="1" stop-color="#9059FF"/>') +
      "</linearGradient></defs>" +
      paths("url(#brand)");
  } else if (id === "chrome") {
    content =
      '<circle cx="12" cy="12" r="12" fill="#EA4335"/><path d="M12 12H24A12 12 0 0 1 6 22.392Z" fill="#FBBC05"/><path d="M12 12L6 22.392A12 12 0 0 1 1.608 6Z" fill="#34A853"/><circle cx="12" cy="12" r="5.6" fill="#FFFFFF"/><circle cx="12" cy="12" r="4.5" fill="#4285F4"/>';
  } else if (id === "gmail") {
    content =
      '<path d="M2 20V5L12 12L22 5V20" fill="none" stroke="#EA4335" stroke-width="4" stroke-linejoin="round"/><path d="M2 20V8" stroke="#4285F4" stroke-width="4"/><path d="M22 20V8" stroke="#34A853" stroke-width="4"/><path d="M2 8V5L6 8" fill="none" stroke="#C5221F" stroke-width="4"/><path d="M18 8L22 5V8" fill="none" stroke="#FBBC04" stroke-width="4"/>';
  } else if (id === "googledrive") {
    content =
      '<path d="M8 2H16L5 21H0Z" fill="#0F9D58"/><path d="M16 2L24 16H16L8 2Z" fill="#F4B400"/><path d="M5 21L9 14H24L20 21Z" fill="#4285F4"/>';
  } else if (id === "googlephotos") {
    content =
      '<path d="M12 12V2A10 10 0 0 1 22 12Z" fill="#EA4335"/><path d="M12 12H22A10 10 0 0 1 12 22Z" fill="#4285F4"/><path d="M12 12V22A10 10 0 0 1 2 12Z" fill="#34A853"/><path d="M12 12H2A10 10 0 0 1 12 2Z" fill="#FBBC04"/>';
  } else if (id === "figma") {
    content =
      '<path d="M12 0H6a6 6 0 0 0 0 12h6Z" fill="#F24E1E"/><path d="M12 0h6a6 6 0 0 1 0 12h-6Z" fill="#FF7262"/><path d="M12 12H6a6 6 0 0 0 0 12h6Z" fill="#A259FF"/><circle cx="18" cy="18" r="6" fill="#1ABCFE"/><path d="M12 24H6a6 6 0 1 0 6 6Z" fill="#0ACF83"/>';
  } else if (id === "snapchat") {
    content =
      '<rect width="24" height="24" rx="5" fill="#FFFC00"/>' +
      paths("#FFFFFF") +
      '<g fill="none" stroke="#111111" stroke-width=".55">' +
      paths("none") +
      "</g>";
  }
  const viewBox =
    normalize && APP_ICON_INK[id]
      ? APP_ICON_INK[id].join(" ")
      : id === "figma"
        ? "0 0 24 36"
        : icon.viewBox;
  const svg =
    '<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="' +
    viewBox +
    '">' +
    content +
    "</svg>";
  return {
    kind: "url",
    url: "data:image/svg+xml;charset=utf-8," + encodeURIComponent(svg),
  };
}
